-- Traducciones (inglés y francés) de los productos existentes.
-- Los textos originales están en español; así los títulos y descripciones no quedan
-- vacíos ni en español al cambiar de idioma. Los materiales se traducen en el frontend
-- (diccionario productData.materials), por eso aquí se dejan vacíos.
-- Es idempotente: no pisa traducciones que ya existan.

INSERT INTO public.product_translations (product_id, language, name, description, materials)
SELECT p.id, v.language, v.name, v.description, '{}'::text[]
FROM (VALUES
  ('Blusa Boho Multicolor', 'en', 'Multicolor Boho Blouse', 'Hand-knit boho top with a beautiful blend of earthy colors. It combines browns, blues and oranges in a one-of-a-kind design.'),
  ('Blusa Boho Multicolor', 'fr', 'Blouse Boho Multicolore', 'Haut boho tricoté à la main avec un joli mélange de couleurs terreuses. Il associe marron, bleu et orange dans un design unique.'),
  ('Blusa Citron Verde', 'en', 'Lime Green Blouse', 'Vibrant lime-green blouse with open lace patterns. Perfect for summer days.'),
  ('Blusa Citron Verde', 'fr', 'Blouse Vert Citron', 'Blouse vert citron éclatante aux motifs de dentelle ajourée. Parfaite pour les journées d’été.'),
  ('Blusa con Fajón Azul', 'en', 'Blue Blouse with Sash', 'Classic blouse with stripes in blue, white and cream. Traditional design with a modern finish.'),
  ('Blusa con Fajón Azul', 'fr', 'Blouse Bleue avec Ceinture', 'Blouse classique à rayures bleues, blanches et crème. Design traditionnel avec une finition moderne.'),
  ('Blusa con Fajón Matizado', 'en', 'Shaded Blouse with Sash', 'Elegant blouse with horizontal stripes in red, blue and cream. Comes with a built-in sash.'),
  ('Blusa con Fajón Matizado', 'fr', 'Blouse Dégradée avec Ceinture', 'Élégante blouse à rayures horizontales rouges, bleues et crème. Ceinture intégrée.'),
  ('Blusa Crema Cruzada', 'en', 'Cream Wrap Blouse', 'Delicate short cream blouse with a crossover design. Ideal to pair with high-waisted skirts.'),
  ('Blusa Crema Cruzada', 'fr', 'Blouse Crème Croisée', 'Délicate blouse courte de couleur crème au design croisé. Idéale avec des jupes taille haute.'),
  ('Blusa Flores y Franjas', 'en', 'Flowers and Fringes Blouse', 'Bohemian top with pink and green floral motifs. Decorative fringes give it a special touch.'),
  ('Blusa Flores y Franjas', 'fr', 'Blouse Fleurs et Franges', 'Haut bohème aux motifs floraux roses et verts. Les franges décoratives lui donnent une touche spéciale.'),
  ('Blusa Granny Azul', 'en', 'Blue Granny Blouse', 'Beautiful navy-blue blouse in granny technique with yellow details. Traditional pattern with a modern touch.'),
  ('Blusa Granny Azul', 'fr', 'Blouse Granny Bleue', 'Magnifique blouse bleu marine en technique granny avec des détails jaunes. Motif traditionnel avec une touche moderne.'),
  ('Blusa Granny con Franjas', 'en', 'Granny Blouse with Fringes', 'Colorful blouse in granny square technique. It combines vibrant colors with hanging fringes for a unique look.'),
  ('Blusa Granny con Franjas', 'fr', 'Blouse Granny à Franges', 'Blouse colorée en technique granny square. Elle associe des couleurs vives à des franges pendantes pour un look unique.'),
  ('Blusa Marina a Rayas', 'en', 'Navy Striped Blouse', 'Sailor-style blouse with blue and white stripes. Includes lace at the neckline and an adjustable drawstring.'),
  ('Blusa Marina a Rayas', 'fr', 'Blouse Marinière à Rayures', 'Blouse de style marin à rayures bleues et blanches. Dentelle à l’encolure et cordon de serrage réglable.'),
  ('Blusa Rosa Encaje', 'en', 'Pink Lace Blouse', 'Delicate pink blouse with intricate lace patterns. Perfect for a romantic, feminine look.'),
  ('Blusa Rosa Encaje', 'fr', 'Blouse Rose en Dentelle', 'Délicate blouse rose aux motifs de dentelle élaborés. Parfaite pour un look romantique et féminin.'),
  ('Chaleco Boho Mandala', 'en', 'Mandala Boho Vest', 'Bohemian vest with colorful mandala circles on a black base. One-of-a-kind design with an adjustable drawstring.'),
  ('Chaleco Boho Mandala', 'fr', 'Veste Boho Mandala', 'Veste bohème avec de colorés cercles mandala sur fond noir. Design unique avec cordon de serrage réglable.'),
  ('Chaleco Corto Vintage Azul', 'en', 'Short Vintage Blue Vest', 'Short blue vest with multicolor floral details. Classic design with a front drawstring.'),
  ('Chaleco Corto Vintage Azul', 'fr', 'Veste Courte Vintage Bleue', 'Veste courte bleue avec des détails floraux multicolores. Design classique avec cordon de serrage sur le devant.'),
  ('Chaleco de Brillo con Borde Negro', 'en', 'Shimmer Vest with Black Trim', 'Long fluffy-textured vest with elegant black trim. Combines sophistication with comfort.'),
  ('Chaleco de Brillo con Borde Negro', 'fr', 'Veste Brillante à Bordure Noire', 'Longue veste à la texture moelleuse avec d’élégantes bordures noires. Elle allie sophistication et confort.'),
  ('Chaleco de Brillo Dorado', 'en', 'Golden Shimmer Vest', 'Elegant long vest made with shimmering golden yarns. Soft, fluffy texture perfect for sophisticated looks.'),
  ('Chaleco de Brillo Dorado', 'fr', 'Veste Brillante Dorée', 'Élégante longue veste en fils dorés brillants. Texture douce et moelleuse, parfaite pour les looks sophistiqués.'),
  ('Chaleco de Brillo Negro', 'en', 'Black Shimmer Vest', 'Elegant black vest with a shiny, fluffy texture. Perfect for sophisticated, modern looks.'),
  ('Chaleco de Brillo Negro', 'fr', 'Veste Brillante Noire', 'Élégante veste noire à la texture brillante et moelleuse. Parfaite pour les looks sophistiqués et modernes.'),
  ('Chaleco Granny Vintage Floral', 'en', 'Floral Granny Vintage Vest', 'Sleeveless vest with beautiful floral motifs in granny technique. White base with colorful details.'),
  ('Chaleco Granny Vintage Floral', 'fr', 'Veste Granny Vintage Fleurie', 'Veste sans manches aux jolis motifs floraux en technique granny. Fond blanc avec des détails colorés.'),
  ('Chaleco Vintage con Flecos', 'en', 'Vintage Vest with Fringes', 'Traditional vest with granny square motifs and decorative fringes. Vibrant colors in a timeless design.'),
  ('Chaleco Vintage con Flecos', 'fr', 'Veste Vintage à Franges', 'Veste traditionnelle aux motifs granny square et franges décoratives. Couleurs vives dans un design intemporel.'),
  ('Chaleco Vintage Multicolor', 'en', 'Multicolor Vintage Vest', 'Spectacular long vest with sleeves and multicolor geometric designs. A unique piece of textile art.'),
  ('Chaleco Vintage Multicolor', 'fr', 'Veste Vintage Multicolore', 'Spectaculaire longue veste avec manches et motifs géométriques multicolores. Une pièce unique d’art textile.'),
  ('Chaleco Vintage Rosa', 'en', 'Pink Vintage Vest', 'Beautiful vest in pink and purple tones using granny square technique. Romantic and versatile design.'),
  ('Chaleco Vintage Rosa', 'fr', 'Veste Vintage Rose', 'Magnifique veste dans des tons rose et violet en technique granny square. Design romantique et polyvalent.'),
  ('Gilet Estilo Mariposa', 'en', 'Butterfly-Style Gilet', 'Delicate butterfly-shaped gilet in soft tones. Romantic design perfect for special occasions.'),
  ('Gilet Estilo Mariposa', 'fr', 'Gilet Style Papillon', 'Délicat gilet en forme de papillon dans des tons doux. Design romantique parfait pour les occasions spéciales.'),
  ('Gilet Granny Café con Franjas', 'en', 'Brown Granny Gilet with Fringes', 'Brown-toned gilet in granny technique with fringes. Classic design that evokes the warmth of traditional knits.'),
  ('Gilet Granny Café con Franjas', 'fr', 'Gilet Granny Marron à Franges', 'Gilet dans des tons marron en technique granny avec franges. Design classique qui évoque la chaleur des tricots traditionnels.'),
  ('Gilet Granny Negro con Franjas', 'en', 'Black Granny Gilet with Fringes', 'Black gilet in granny square technique with decorative fringes. Perfect for an elegant, timeless look.'),
  ('Gilet Granny Negro con Franjas', 'fr', 'Gilet Granny Noir à Franges', 'Gilet noir en technique granny square avec franges décoratives. Parfait pour un look élégant et intemporel.'),
  ('Gilet Granny Negro Elegante', 'en', 'Elegant Black Granny Gilet', 'Elegant black gilet with a sophisticated granny pattern. Perfect for urban looks with a handcrafted touch.'),
  ('Gilet Granny Negro Elegante', 'fr', 'Gilet Granny Noir Élégant', 'Élégant gilet noir au motif granny sophistiqué. Parfait pour des looks urbains avec une touche artisanale.'),
  ('Gilet Mandala con Mangas', 'en', 'Mandala Gilet with Sleeves', 'Mandala gilet with built-in sleeves. Intricate design that combines tradition and modernity in every stitch.'),
  ('Gilet Mandala con Mangas', 'fr', 'Gilet Mandala avec Manches', 'Gilet mandala avec manches intégrées. Un design complexe qui allie tradition et modernité à chaque maille.'),
  ('Gilet Mandala Rosa', 'en', 'Pink Mandala Gilet', 'Romantic pink gilet with a delicate mandala design. Combines femininity with the strength of handmade knitwear.'),
  ('Gilet Mandala Rosa', 'fr', 'Gilet Mandala Rose', 'Romantique gilet rose au délicat motif mandala. Il allie féminité et force du tricot artisanal.'),
  ('Gilet Mandala Sin Mangas', 'en', 'Sleeveless Mandala Gilet', 'Elegant gilet with a hand-knit mandala design. Earthy colors create a hypnotic, bohemian pattern.'),
  ('Gilet Mandala Sin Mangas', 'fr', 'Gilet Mandala Sans Manches', 'Élégant gilet au motif mandala tricoté à la main. Des couleurs terreuses créent un motif hypnotique et bohème.'),
  ('Gilet Mandala Verde Citron', 'en', 'Lime Green Mandala Gilet', 'Refreshing lime-green gilet with a mandala pattern. Perfect for spring and summer with its vibrant color.'),
  ('Gilet Mandala Verde Citron', 'fr', 'Gilet Mandala Vert Citron', 'Gilet vert citron rafraîchissant avec un motif mandala. Parfait pour le printemps et l’été grâce à sa couleur vive.'),
  ('Gilet Multicolor con Franjas', 'en', 'Multicolor Gilet with Fringes', 'Vibrant multicolor gilet with hanging fringes. Combines many shades for a bohemian, youthful look.'),
  ('Gilet Multicolor con Franjas', 'fr', 'Gilet Multicolore à Franges', 'Gilet multicolore éclatant avec franges pendantes. Il associe de multiples tons pour un look bohème et jeune.'),
  ('Gilet Multicolor Especial', 'en', 'Special Multicolor Gilet', 'Vibrant multicolor gilet with floral textures in blue, orange, yellow and pink. A unique design that blends many colors in perfect harmony.'),
  ('Gilet Multicolor Especial', 'fr', 'Gilet Multicolore Spécial', 'Gilet multicolore éclatant aux textures florales bleues, orange, jaunes et roses. Un design unique qui marie de nombreuses couleurs en parfaite harmonie.'),
  ('Túnica de Punta Negra y Roja', 'en', 'Black and Red Pointed Tunic', 'Striking asymmetric poncho-style tunic in black and red. The geometric zigzag design combines openwork netting with contrasting stripes. The sides fall into points, creating a dramatic, modern silhouette. The short sleeves carry the same decorative pattern. A unique piece of textile art, perfect for standing out on any occasion. Only the piece shown is available, hand-knit by Yaritza Salgado Fina.'),
  ('Túnica de Punta Negra y Roja', 'fr', 'Tunique à Pointes Noire et Rouge', 'Tunique asymétrique de style poncho, noire et rouge, saisissante. Le design géométrique en zigzag associe un filet ajouré à des rayures contrastées. Les côtés retombent en pointe, créant une silhouette spectaculaire et moderne. Les manches courtes reprennent le même motif décoratif. Une pièce unique d’art textile, parfaite pour se démarquer en toute occasion. Seule la pièce présentée est disponible, tricotée à la main par Yaritza Salgado Fina.'),
  ('Túnica Larga Azul Cielo', 'en', 'Long Sky-Blue Tunic', 'Beautiful long tunic in vibrant sky blue with a very open net design. The upper medallion and the openwork netting create a striking visual effect. Short sleeves and a hem with decorative waves complete this bohemian design. Perfect for the beach or casual summer events. Each piece is unique, only the piece shown is available, handmade by Yaritza Salgado Fina.'),
  ('Túnica Larga Azul Cielo', 'fr', 'Longue Tunique Bleu Ciel', 'Magnifique longue tunique d’un bleu ciel éclatant au design de filet très ouvert. Le médaillon supérieur et le filet ajouré créent un effet visuel impressionnant. Les manches courtes et l’ourlet aux ondulations décoratives complètent ce design bohème. Parfaite pour la plage ou les événements estivaux décontractés. Chaque pièce est unique, seule la pièce présentée est disponible, créée à la main par Yaritza Salgado Fina.'),
  ('Túnica Larga Crema con Mangas', 'en', 'Long Cream Tunic with Sleeves', 'Elegant long tunic hand-knit in a natural cream shade. It features a beautiful openwork net design with floral details on the edges and flared sleeves. This unique piece is perfect as a beach cover-up or over a basic dress. The handcrafted work includes a central medallion on the back and wavy finishes on the hem. Only the piece shown is available, handmade by Yaritza Salgado Fina.'),
  ('Túnica Larga Crema con Mangas', 'fr', 'Longue Tunique Crème avec Manches', 'Élégante longue tunique tricotée à la main dans un ton crème naturel. Elle présente un joli design de filet ajouré avec des détails de fleurs sur les bords et des manches évasées. Cette pièce unique est parfaite en robe de plage ou portée sur une robe simple. Le travail artisanal comprend un médaillon central dans le dos et des finitions ondulées à l’ourlet. Seule la pièce présentée est disponible, faite à la main par Yaritza Salgado Fina.'),
  ('Túnica Larga Rosa Delicada', 'en', 'Delicate Long Pink Tunic', 'Romantic long tunic in a soft shaded pink. The openwork design reveals delicate net and flower patterns, with a beautiful circular medallion on the back. Short butterfly-style sleeves add a feminine touch. Ideal for special events or as an elegant beach cover-up. A one-of-a-kind, unrepeatable piece, entirely hand-knit by Yaritza Salgado Fina.'),
  ('Túnica Larga Rosa Delicada', 'fr', 'Longue Tunique Rose Délicate', 'Romantique longue tunique d’un rose doux dégradé. Le design ajouré laisse voir de délicats motifs de filet et de fleurs, avec un joli médaillon circulaire dans le dos. Les manches courtes papillon ajoutent une touche féminine. Idéale pour les occasions spéciales ou comme élégante sortie de plage. Pièce unique et irrépétable, entièrement tricotée à la main par Yaritza Salgado Fina.'),
  ('Túnica Mandala Multicolor', 'en', 'Multicolor Mandala Tunic', 'Extraordinary sleeveless tunic with a mandala design and circles in vibrant colors. The back features a large multicolor circular mandala, while the lower part combines turquoise circles with orange, pink, yellow and green details. The hem ends in a blue and yellow zigzag pattern. A true work of textile art that takes hours of handcrafted work. A one-of-a-kind, unrepeatable piece, completely hand-knit by Yaritza Salgado Fina.'),
  ('Túnica Mandala Multicolor', 'fr', 'Tunique Mandala Multicolore', 'Extraordinaire tunique sans manches au design de mandala et de cercles aux couleurs vives. Le dos présente un grand mandala circulaire multicolore, tandis que le bas associe des cercles turquoise à des détails orange, roses, jaunes et verts. L’ourlet se termine par un motif en zigzag bleu et jaune. Une véritable œuvre d’art textile qui demande des heures de travail artisanal. Pièce unique et irrépétable, entièrement tricotée à la main par Yaritza Salgado Fina.'),
  ('Vestido Blanco Mandala Corto', 'en', 'Short White Mandala Dress', 'Beautiful short white dress with circular mandala designs on the bodice. The neckline has decorative drawstring details and delicate short sleeves. The openwork skirt creates a light, elegant effect. Perfect for special events or summer outings. A unique piece, completely hand-knit.'),
  ('Vestido Blanco Mandala Corto', 'fr', 'Robe Courte Blanche Mandala', 'Magnifique robe courte blanche avec des motifs de mandalas circulaires sur le corsage. L’encolure présente des détails de cordon décoratif et de délicates manches courtes. La jupe au point ajouré crée un effet léger et élégant. Parfaite pour les occasions spéciales ou les sorties d’été. Pièce unique, entièrement tricotée à la main.'),
  ('Vestido Chocolate Elegante', 'en', 'Elegant Chocolate Dress', 'Elegant short dress in a deep chocolate shade with openwork mandala designs on the bodice. The short sleeves carry the same delicate circular pattern. The waist is defined by a ribbed knit, followed by a skirt with more openwork patterns. A sophisticated dress perfect for day or night events.'),
  ('Vestido Chocolate Elegante', 'fr', 'Robe Chocolat Élégante', 'Élégante robe courte d’un chocolat intense avec des mandalas ajourés sur le corsage. Les manches courtes reprennent le même délicat motif circulaire. La taille est marquée par un tricot côtelé, suivi d’une jupe à d’autres motifs ajourés. Une robe sophistiquée, parfaite pour les événements de jour comme de nuit.'),
  ('Vestido con Franjas Multicolor', 'en', 'Multicolor Striped Dress', 'Vibrant halter dress with a striped design in pink, green and white. The cream openwork bodice contrasts beautifully with the striped skirt. The back has a decorative drawstring closure that allows a custom fit. Perfect for bohemian looks and summer festivals.'),
  ('Vestido con Franjas Multicolor', 'fr', 'Robe à Rayures Multicolores', 'Éclatante robe dos-nu à rayures roses, vertes et blanches. Le corsage crème au point ajouré contraste joliment avec la jupe rayée. Le dos présente une fermeture à cordon décoratif qui permet un ajustement personnalisé. Parfaite pour les looks bohèmes et les festivals d’été.'),
  ('Vestido Extra Largo Crema', 'en', 'Extra-Long Cream Dress', 'Spectacular long dress in cream with a sophisticated design. The bodice features a net weave with a decorative collar and short sleeves. The middle section adds hanging fringes for movement, followed by a long skirt with a zigzag pattern. An elegant piece perfect for special occasions or as a luxury beach dress.'),
  ('Vestido Extra Largo Crema', 'fr', 'Robe Extra Longue Crème', 'Spectaculaire robe longue de couleur crème au design sophistiqué. Le corsage présente un tricot en filet avec un col décoratif et des manches courtes. La partie centrale ajoute des franges pendantes qui apportent du mouvement, suivies d’une longue jupe à motif zigzag. Une pièce élégante, parfaite pour les occasions spéciales ou comme robe de plage de luxe.'),
  ('Vestido Multicolor con Mangas', 'en', 'Multicolor Dress with Sleeves', 'Spectacular dress with long sleeves and a multicolor geometric design. The bodice combines cream with red, black and turquoise details, creating a beautiful tribal pattern. The skirt features wavy stripes in assorted colors: pink, green, black and cream. A true work of textile art that stands out for its complexity and beauty.'),
  ('Vestido Multicolor con Mangas', 'fr', 'Robe Multicolore avec Manches', 'Spectaculaire robe à manches longues et au design géométrique multicolore. Le corsage associe le crème à des détails rouges, noirs et turquoise, créant un magnifique motif tribal. La jupe présente des rayures ondulées de couleurs variées : rose, vert, noir et crème. Une véritable œuvre d’art textile qui se distingue par sa complexité et sa beauté.')
) AS v(es_name, language, name, description)
JOIN public.products p ON p.name = v.es_name
ON CONFLICT (product_id, language) DO NOTHING;
